const lessons=[{"sentences":[{"speaker":"A","text":"Hi Mark we really need to plan our trip to the modern art museum this weekend.","position":1,"audioStartSeconds":0,"audioEndSeconds":5.0307916666666666},{"speaker":"B","text":"Hello Sarah I have been looking at the schedule and we should decide how to travel there.","position":2,"audioStartSeconds":5.230791666666667,"audioEndSeconds":10.287333333333333},{"speaker":"A","text":"Although driving sounds comfortable the parking fees near the gallery are extremely expensive.","position":3,"audioStartSeconds":10.487333333333334,"audioEndSeconds":16.248416666666667},{"speaker":"B","text":"That is very true because city centre parking usually costs twenty pounds for the whole day.","position":4,"audioStartSeconds":16.448416666666667,"audioEndSeconds":22.18375},{"speaker":"A","text":"We could take the underground train if we want to avoid all that terrible traffic.","position":5,"audioStartSeconds":22.38375,"audioEndSeconds":27.357958333333332},{"speaker":"B","text":"The metro is fast but it is always crowded when people travel on Saturday mornings.","position":6,"audioStartSeconds":27.557958333333332,"audioEndSeconds":32.88008333333333},{"speaker":"A","text":"What about catching the local express bus since the stop is right outside my apartment building?","position":7,"audioStartSeconds":33.080083333333334,"audioEndSeconds":38.71154166666667},{"speaker":"B","text":"Taking the bus sounds brilliant because we can enjoy the view and save some money.","position":8,"audioStartSeconds":38.911541666666665,"audioEndSeconds":43.83425},{"speaker":"A","text":"Now we also need to figure out the best way to purchase our entrance tickets.","position":9,"audioStartSeconds":44.03425,"audioEndSeconds":48.750708333333336},{"speaker":"B","text":"Buying them online beforehand is much cheaper than paying at the main entrance desk.","position":10,"audioStartSeconds":48.95070833333333,"audioEndSeconds":54.05379166666667},{"speaker":"A","text":"If we book through the museum website today we get a ten percent discount.","position":11,"audioStartSeconds":54.253791666666665,"audioEndSeconds":59.047625},{"speaker":"B","text":"That is wonderful news because every little saving helps us buy extra coffee later.","position":12,"audioStartSeconds":59.247625,"audioEndSeconds":64.544},{"speaker":"A","text":"Should we visit the special sculpture exhibition or just look at the permanent collections?","position":13,"audioStartSeconds":64.744,"audioEndSeconds":70.13058333333333},{"speaker":"B","text":"The sculpture exhibition looks fascinating although it requires an extra ticket upgrade.","position":14,"audioStartSeconds":70.33058333333334,"audioEndSeconds":75.82029166666666},{"speaker":"A","text":"Let us buy the combined ticket so we do not miss any of the amazing galleries.","position":15,"audioStartSeconds":76.02029166666667,"audioEndSeconds":80.981625},{"speaker":"B","text":"I agree completely with your idea for the tickets.","position":16,"audioStartSeconds":81.181625,"audioEndSeconds":84.75120833333334},{"speaker":"A","text":"I will book the tickets on my laptop right now while you check the bus timetable.","position":17,"audioStartSeconds":84.95120833333333,"audioEndSeconds":89.89225},{"speaker":"B","text":"Perfect plan because everything will be ready for our wonderful Saturday adventure.","position":18,"audioStartSeconds":90.09225,"audioEndSeconds":95.37695833333333}],"questions":[{"prompt":"What is the primary purpose of the conversation?","options":["To plan transport and ticket options for a museum visit.","To complain about the high cost of modern art galleries.","To reschedule a weekend meeting with friends."],"answer":"A","evidenceSentence":1,"evidence":"plan our trip to the modern art museum","explanation":"Hai người bạn đang bàn bạc và lên kế hoạch cho chuyến đi bảo tàng nghệ thuật hiện đại vào cuối tuần này."},{"prompt":"Why do they decide not to drive a car?","options":["The car needs repair work.","Parking fees are too expensive.","The highway is closed for repairs."],"answer":"B","evidenceSentence":3,"evidence":"parking fees near the gallery are extremely expensive","explanation":"Họ quyết định không lái xe vì phí đậu xe gần phòng trưng bày quá đắt đỏ."},{"prompt":"What transport option do they finally choose?","options":["The underground train.","A rented car.","The local express bus."],"answer":"C","evidenceSentence":8,"evidence":"Taking the bus sounds brilliant","explanation":"Họ chọn đi xe buýt tốc hành vì trạm dừng ngay bên ngoài tòa nhà căn hộ của Sarah."},{"prompt":"What advantage do they get by buying tickets online?","options":["They receive a ten percent discount.","They get free lunch at the cafe.","They skip the security check completely."],"answer":"A","evidenceSentence":11,"evidence":"we get a ten percent discount","explanation":"Nếu đặt vé qua trang web của bảo tàng hôm nay, họ sẽ nhận được mức giảm giá mười phần trăm."},{"prompt":"What kind of exhibition do they decide to visit?","options":["Only the permanent collections.","The special sculpture exhibition.","A photography showcase."],"answer":"B","evidenceSentence":15,"evidence":"Let us buy the combined ticket so we do not miss any of the amazing galleries","explanation":"Họ quyết định mua vé kết hợp để xem cả triển lãm điêu khắc đặc biệt lẫn bộ sưu tập thông thường."},{"prompt":"What will A do next?","options":["Check the bus timetable.","Book the tickets on the laptop.","Call the museum customer service."],"answer":"B","evidenceSentence":17,"evidence":"I will book the tickets on my laptop right now","explanation":"Nhân vật A sẽ tiến hành đặt vé trên máy tính xách tay ngay lập tức."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
